--
-- Dumping data for table `league_information`
--

INSERT INTO `league_information` (`season_id`, `about`, `rules`, `news`) VALUES
(12, 'The Ascent Draft League is a competitive Pokémon draft-style league focused on strategy, team building, and player skill. Each participant drafts a unique roster of Pokémon across multiple tiers, creating balanced and diverse teams for the season. \r\n\r\nThe league is structured into a Round Robin stage followed by a Knockout stage, where players compete in Best-of-One matches. Success depends on preparation, adaptability, and smart roster management, including limited mid-season trades.\r\n\r\nPlayers are responsible for scheduling their own matches and are expected to maintain clear communication and respectful conduct throughout the season. The Ascent Draft League is designed to deliver a competitive yet community-driven experience for all participants. ', 'General Rules\r\n- Each team consists of 12 Pokémon total, with 3 Pokémon selected from each tier.\r\n- All matches are Best of 1.\r\n- Players are expected to complete all scheduled matches within the season timeframe.\r\n- Following the draft, each player will be permitted to make up to 2 trades, replacing Pokémon with others from the same tier only, until the end of the following day.\r\n- At the start of each match, players are encouraged to share the battle link in the general Discord chat for community viewing.\r\n- After each match, at least one participant must post the replay in the designated Discord replay channel.\r\n- All participants are expected to maintain respectful conduct at all times and contribute to a positive competitive environment.\r\nRound Robin Stage\r\n- The Round Robin stage will run for approximately 2–3 weeks, with final duration subject to adjustment based on league size and scheduling.\r\n- Each player is required to face every other player at least once. If divisions are implemented, players must compete against all opponents within their division.\r\n- Players are responsible for organizing their own match schedule.\r\nCommunication between opponents is strongly encouraged, preferably through Discord, to ensure timely scheduling and completion of matches.\r\nKnockout Stage Rules\r\n- Prior to the start of the Knockout Stage, each player will be allowed to perform up to 2 Pokémon substitutions, replacing Pokémon with others from the same tier, to better prepare for matchups.\r\n- After Round 1 of the Knockout Stage, players may make 1 Pokémon substitution between each subsequent match, including the Grand Finals reset if applicable.\r\n- Any traded Pokémon must be communicated to the opponent at least 24 hours before the scheduled match time.\r\n- Opponents may choose to accept the updated roster earlier than the 24-hour minimum if both parties agree.', 'Matches can begin!'),
(999, 'The Ascent Draft League is a competitive Pokémon draft-style league focused on strategy, team building, and player skill. Each participant drafts a unique roster of Pokémon across multiple tiers, creating balanced and diverse teams for the season. \n\nThe league is structured into a Round Robin stage followed by a Knockout stage, where players compete in Best-of-One matches. Success depends on preparation, adaptability, and smart roster management, including limited mid-season trades.\n\nPlayers are responsible for scheduling their own matches and are expected to maintain clear communication and respectful conduct throughout the season. The Ascent Draft League is designed to deliver a competitive yet community-driven experience for all participants. ', 'General Rules\r\nEach team consists of 12 Pokémon total, with 3 Pokémon selected from each tier.\r\nAll matches are Best of 1.\r\nPlayers are expected to complete all scheduled matches within the season timeframe.\r\nFollowing the draft, each player will be permitted to make up to 2 trades, replacing Pokémon with others from the same tier only, until the end of the following day.\r\nAt the start of each match, players are encouraged to share the battle link in the general Discord chat for community viewing.\r\nAfter each match, at least one participant must post the replay in the designated Discord replay channel.\r\nAll participants are expected to maintain respectful conduct at all times and contribute to a positive competitive environment.\r\nRound Robin Stage\r\nThe Round Robin stage will run for approximately 2–3 weeks, with final duration subject to adjustment based on league size and scheduling.\r\nEach player is required to face every other player at least once. If divisions are implemented, players must compete against all opponents within their division.\r\nPlayers are responsible for organizing their own match schedule.\r\nCommunication between opponents is strongly encouraged, preferably through Discord, to ensure timely scheduling and completion of matches.\r\nKnockout Stage Rules\r\nPrior to the start of the Knockout Stage, each player will be allowed to perform up to 2 Pokémon substitutions, replacing Pokémon with others from the same tier, to better prepare for matchups.\r\nAfter Round 1 of the Knockout Stage, players may make 1 Pokémon substitution between each subsequent match, including the Grand Finals reset if applicable.\r\nAny traded Pokémon must be communicated to the opponent at least 24 hours before the scheduled match time.\r\nOpponents may choose to accept the updated roster earlier than the 24-hour minimum if both parties agree.', 'Welcome to the inaugural season of the Ascent Draft League! Trainers have drafted their teams and the competition is officially underway. Stay active, schedule your matches, and submit replays after each battle. Good luck to all competitors—may the best strategist win! ');

